import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and the current year `now`.

    The current year is supplied by the caller; the clock is never read.
    Returns now - born. Raises ValueError if now < born (born in the future).
    """
    if now < born:
        raise ValueError("born year is after the current year")
    return now - born


def test_age_basic() -> None:
    assert age_at(1990, 2024) == 34


def test_age_same_year_is_zero() -> None:
    assert age_at(2024, 2024) == 0


def test_age_one_year() -> None:
    assert age_at(2023, 2024) == 1


def test_age_long_span() -> None:
    assert age_at(1900, 2000) == 100


def test_age_negative_years() -> None:
    # Years before year 0 still subtract arithmetically.
    assert age_at(-100, 50) == 150


def test_age_returns_int() -> None:
    assert isinstance(age_at(2000, 2010), int)


def test_age_born_in_future_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_age_born_one_year_in_future_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)


@pytest.mark.parametrize(
    ("born", "now", "expected"),
    [
        (2000, 2000, 0),
        (2000, 2001, 1),
        (1985, 2025, 40),
        (1, 2024, 2023),
    ],
)
def test_age_parametrized(born: int, now: int, expected: int) -> None:
    assert age_at(born, now) == expected

